/// `ochid:` trailers.
fn opening_body(repo: &Path) -> Result<String, Box<dyn std::error::Error>> {
    let desc = jj::desc_of(repo, "@-")?;
    Ok(desc
        .lines()
        .skip(1)
        .filter(|l| !l.starts_with("ochid:"))
        .collect::<Vec<_>>()
        .join("\n")
        .trim()
        .to_string())
}

/// Finalize a single-step cycle's one commit in place: fold the work
